definition.script:
node {
    timestamps {
        stage('Build and deploy Service dev on Primary') {
            sh "ssh -o BatchMode=yes -o UserKnownHostsFile=/var/jenkins_home/.ssh/known_hosts -i /var/jenkins_home/.ssh/primary_test root@100.86.10.52 '/opt/tolink/test/build-component-on-primary.sh service ${env.BUILD_NUMBER}'"
        }
        currentBuild.description = "dev / Primary / test-dev-b${env.BUILD_NUMBER}"
    }
}
